import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { createServer } from "node:http";
import { test } from "node:test";
import { promisify } from "node:util";
import { branchOf, byBranch, isUntagged, matches } from "../src/filter.ts";
import type { EnvctlResource } from "../src/filter.ts";
import { buildPlan } from "../src/plan.ts";

function resource(id: string, extra: Partial<EnvctlResource> = {}): EnvctlResource {
  return {
    id, type: "instance", name: id, tags: {}, stack_id: null,
    depends_on: [], cost_month_cents: 100, created_at: "2024-11-01T00:00:00Z",
    ...extra,
  };
}

test("label keys are case-insensitive, values are exact, and legacy tags take precedence", () => {
  for (const key of ["branch", "Branch", "BRANCH", "bRaNcH"]) {
    const r = resource("cdk", { labels: { [key]: "feat-a", Team: "Payments" } });
    assert.equal(branchOf(r), "feat-a");
    assert.equal(isUntagged(r), false);
    assert.equal(byBranch([r]).get("feat-a")?.length, 1);
    assert.ok(matches(r, [["branch", "feat-a"], ["team", "Payments"]]));
    assert.ok(!matches(r, [["branch", "FEAT-A"]]));
    assert.ok(!matches(r, [["team", "payments"]]));
  }
  assert.equal(branchOf(resource("legacy", {
    tags: { branch: "feat-legacy" }, labels: { Branch: "feat-other" },
  })), "feat-legacy");
  assert.equal(branchOf(resource("none")), undefined);
  assert.equal(isUntagged(resource("none")), true);
  assert.equal(isUntagged(resource("team-only", { labels: { Team: "payments" } })), true);
});

test("plans include labels and stack companions without sweeping in other branches", () => {
  const resources = [
    resource("network", { tags: { branch: "feat-a" }, stack_id: "stk-feat-a", depends_on: [] }),
    resource("volume", { stack_id: "stk-cdk-a" }),
    resource("instance", { labels: { Branch: "feat-a" }, stack_id: "stk-cdk-a", depends_on: ["network", "volume"] }),
    resource("dns", { labels: { BRANCH: "feat-a" }, depends_on: ["instance"] }),
    resource("boot", { stack_id: "stk-feat-a" }),
    resource("prefix", { stack_id: "stk-feat-a-v2" }),
    resource("other-label", { labels: { Branch: "feat-other" }, stack_id: "stk-feat-a" }),
    resource("other-tag", { tags: { branch: "feat-other" }, stack_id: "stk-feat-a" }),
    resource("different-case", { labels: { Branch: "FEAT-A" } }),
    resource("orphan"),
  ];
  const plan = buildPlan(resources, "feat-a");
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map(r => r.id).sort(), ["boot", "dns", "instance", "network", "volume"]);
  const position = (id: string) => plan.steps.findIndex(r => r.id === id);
  assert.ok(position("dns") < position("instance"));
  assert.ok(position("instance") < position("network"));
  assert.ok(position("instance") < position("volume"));
  const external = resource("external", { labels: { Branch: "feat-other" }, depends_on: ["network"] });
  assert.deepEqual(buildPlan([...resources, external], "feat-a").blocked,
    [{ id: "network", dependents: ["external"] }]);
});

const exec = promisify(execFile);

test("CLI preserves labels across API pages and safely tears down only the requested branch", async (t) => {
  const resources = new Map<string, EnvctlResource>();
  resources.set("network", resource("network", { tags: { branch: "feat-a" }, stack_id: "stk-feat-a" }));
  for (let i = 0; i < 19; i++) {
    resources.set(`unrelated-${i}`, resource(`unrelated-${i}`, { tags: { branch: "main" } }));
  }
  resources.set("instance", resource("instance", { labels: { Branch: "feat-a" }, depends_on: ["network"] }));
  resources.set("dns", resource("dns", { labels: { BRANCH: "feat-a" }, depends_on: ["instance"] }));
  resources.set("prefix", resource("prefix", { stack_id: "stk-feat-a-v2" }));
  const deleted: string[] = [];
  const cursors: string[] = [];
  const server = createServer((req, res) => {
    res.setHeader("content-type", "application/json");
    if (req.headers.authorization !== "Bearer test-token") {
      res.writeHead(401).end(JSON.stringify({ error: "unauthorized" }));
      return;
    }
    const url = new URL(req.url!, "http://localhost");
    if (req.method === "GET" && url.pathname === "/v1/resources") {
      const cursor = url.searchParams.get("cursor")!;
      cursors.push(cursor);
      const start = Number(cursor);
      const all = [...resources.values()];
      res.end(JSON.stringify({
        resources: all.slice(start, start + 20),
        next_cursor: start + 20 < all.length ? String(start + 20) : null,
      }));
      return;
    }
    if (req.method === "DELETE") {
      const id = decodeURIComponent(url.pathname.slice("/v1/resources/".length));
      const dependents = [...resources.values()].filter(r => r.depends_on.includes(id));
      if (dependents.length) {
        res.writeHead(409).end(JSON.stringify({ error: "resource has dependents" }));
        return;
      }
      resources.delete(id);
      deleted.push(id);
      res.end(JSON.stringify({ deleted: id }));
      return;
    }
    res.writeHead(404).end(JSON.stringify({ error: "not found" }));
  });
  await new Promise<void>(resolve => server.listen(0, "127.0.0.1", resolve));
  t.after(() => new Promise<void>((resolve, reject) => server.close(err => err ? reject(err) : resolve())));
  const address = server.address();
  assert.ok(address && typeof address !== "string");
  const run = (...args: string[]) => exec(process.execPath,
    ["--experimental-strip-types", "--no-warnings", "src/cli.ts", ...args], {
      env: { ...process.env, ENVCTL_API: `http://127.0.0.1:${address.port}`, ENVCTL_TOKEN: "test-token" },
    });

  const plan = JSON.parse((await run("plan", "--branch", "feat-a", "--json")).stdout);
  assert.deepEqual(plan.blocked, []);
  assert.deepEqual(plan.steps.map((r: { id: string }) => r.id), ["dns", "instance", "network"]);
  assert.deepEqual(cursors, ["0", "20"]);
  assert.match((await run("list")).stdout, /feat-a\s+3\s+\$3\.00/);
  assert.match((await run("gc", "--untagged")).stdout, /1 untagged resources/);
  await run("teardown", "--branch", "feat-a", "--dry-run");
  assert.deepEqual(deleted, []);

  resources.set("external", resource("external", { labels: { Branch: "main" }, depends_on: ["network"] }));
  await assert.rejects(run("teardown", "--branch", "feat-a"), (err: Error & { stderr?: string }) => {
    assert.match(err.stderr ?? "", /refusing to tear down/);
    return true;
  });
  assert.deepEqual(deleted, []);
  resources.delete("external");
  assert.match((await run("teardown", "--branch", "feat-a")).stdout, /complete \(3 resources\)/);
  assert.deepEqual(deleted, ["dns", "instance", "network"]);
  assert.equal(resources.size, 20);
  assert.ok(resources.has("prefix"));
});
