test("label keys are case-insensitive, values exact, and tags take precedence", () => {
  for (const key of ["branch", "Branch", "BRANCH", "bRaNcH"]) {
    const r = resource("cdk", { labels: { [key]: "feat-a", Team: "Payments" } });
    assert.equal(branchOf(r), "feat-a");
    assert.equal(isUntagged(r), false);
    assert.equal(byBranch([r]).get("feat-a")?.length, 1);
    assert.ok(matches(r, [["branch", "feat-a"], ["team", "Payments"]]));
    assert.ok(!matches(r, [["branch", "FEAT-A"]]));
    assert.ok(!matches(r, [["team", "payments"]]));
  }
  assert.equal(branchOf(resource("legacy", {
    tags: { branch: "feat-legacy" }, labels: { Branch: "feat-other" },
  })), "feat-legacy");
  assert.equal(branchOf(resource("none")), undefined);
  assert.equal(isUntagged(resource("none")), true);
  assert.equal(isUntagged(resource("team-only", { labels: { Team: "payments" } })), true);
});

